from collections import defaultdict, deque
from math import gcd

def shortest_path(n, M, edges):
    distances = [0] * n
    dp = [0] * n
    graph = defaultdict(list)

    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    queue = deque([(0, 0)])  # (node, distance)
    while queue:
        node, dist = queue.popleft()
        if dist % M != 0:
            dp[node] = -1
            continue
        if dist == distances[node]:
            # Skip paths that are not the shortest
            continue
        for neighbor, weight in graph[node]:
            new_dist = (dist * 10 + weight) % (M * 9)
            if new_dist % M == 0 and new_dist * 9 >= M:
                if dp[neighbor] == -1:
                    dp[neighbor] = -1
                elif dp[neighbor] < new_dist:
                    vp = [dp[neighbor], dp[node]]
                    vpp = [new_dist, pp]
                    dp[neighbor], pp = sorted(vpp)[0], sorted(vpp)[1]
                    queue.append((neighbor, new_dist))
            elif new_dist % M != 0 and new_dist * 10 % M == 0:
                if pp == -1:
                    pp = new_dist
                else:
                    dp[neighbor] = new_dist
                    queue.append((neighbor, new_dist))

    return sum(dp)

