from collections import defaultdict
from heapq import heappop, heappush
from typing import List

def create_tree(edges: List[List[int]]) -> None:
    global vertex
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    vertex = 1
    return

def f(parent: List[int], index: int) -> int:
    global leaves
    while parent[index] != index:
        index = parent[index]
    leaves.add(index)
    return index

def max_f(index: int) -> int:
    global max_v, max_index
    while parent[index] != index:
        index = parent[index]
    if len(leaves) < q - 1:
        return index
    f(parent, max_index)
    max_v = max(parent[i] for i in leaves)
    parent[index] = max_index
    heappush(leaves, max_index)
    return max_index

def when(index: int) -> int:
    global max_v, max_index
    if len(leaves) >= 2:
        v1 = f(parent, max_index)
        max_v = max(max_v, v1)
        index = heappop(leaves)

    if len(leaves) > q - 1:
        return q + 1
    while parent[index] != index:
        index = parent[index]
    return index + max_f(index)

def compare(index1: int, index2: int) -> int:
    global max_v
    if index1 == index2:
        return index1
    return max(index1, index2)

