import sys
from collections import defaultdict

def build_graph(edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    return graph

def find_paths(graph, vertices):
    path_lengths = {}
    queue = [n for n in range(1, len(vertices) + 1)]
    lengths = 0
    while queue:
        n = queue.pop(len(queue) - 1)
        if n in path_lengths:
            lengths -= path_lengths.pop(n) * 1.0
        new_lengths = 1
        for next_n in graph[n]:
            weights = [len(graph[n][prec]) for prec in graph if n in graph[n]]
            v_min = min(weights)
            v_max = max(weights)
            if v_min == 1:
                continue

            # we can add v_min
            new_lengths += v_max
            weights.pop(weights.index(v_min))
            weights.sort()
            if len(weights) > 1:
                weights.index(v_min)
                weights[v_min-1] += v_min
                new_lengths -= v_max

            path_lengths[n] = new_lengths
            if len(weights) > 1:
                queue.append(n)
        queue.append(v_min)
    lengths += path_lengths.pop(n) * 1.0

    path_lengths = {i: len(graph[str(i)]) if str(i) in graph else 1 for i in range(1, len(vertices) + 1)}
    return path_lengths, lengths

def get_paths(paths):
    pos, new_pos = 0, 0
    edge_paths = defaultdict(list)
    while new_pos < len(paths):
        rest = len(paths) - new_pos
        edges = [paths[new_pos + i] for i in range(rest)]
        for edge in edges:
            if edge == None:
                continue
            if pos == 0:
                pos = 0
            prev_end = pos
            while edges:
                edge = edges.pop(0)
                if edge == None:
                    continue
                curr_pos = find_next_end(new_pos + prev_end, new_pos + len(edge_paths), edges)
                new_node = len(edge_paths)
                new_pos += max(curr_pos - new_pos, 1)
                for end in edge:
                    if end == None:
                        continue
                    edge_paths[end] = max(edge_paths[end], new_node)
        pos += rest
        while pos > -1 and pos in edge_paths:
            del edge_paths[pos]
        new_pos += len(edge_paths)
    return edge_paths

def find_next_end(start, end_cond, paths):
    for length in range(start, end_cond):
        new_path_set = set()
        for path in paths:
            node = path[path.find(str(length)):]
            if node.find(str(length + length)) > -1:
                new_path_set.add(path)
        if len(new_path_set) <= 1:
            return length

    return -1

def main():
    n = int(sys.stdin.readline().strip())
    edges = []
    for i in range(n-1):
        edges.extend([int(x) for x in sys.stdin.readline().strip().split()])
    m = int(sys.stdin.readline().strip())
    paths = []
    for i in range(m):
        paths.append([int(x) - 1 for x in sys.stdin.readline().strip().split()])
    for path in paths:
        if len(path) > 1:
            path[-1] = path.pop(0)
    graph = build_graph(edges)
    paths, lengths = build_paths(graph, paths)
    edge_nodes = get_paths(paths)
    answer = 0
    for path_length in paths.values():
        paths_len = path_length
        for edge_nodes in paths_len:
            answer += paths[edge_nodes]
    print(answer)

if __name__ == "__main__":
    main()
