            merged += A[i:]
            break
        if A[i] == '0' and B[j] == '0':
            if i < len(A) and j < len(B):
                if A[i] == '0':
                    merged += '1' if B[j] == '0' else '0'
                elif B[j] == '0':
                    merged += '0' if A[i] == '1' else '1'
            elif i < len(A) and j < len(B):
                if A[i] == '0':
                    merged += '1'
                    inversion_count += 1
                else:
                    merged += '0'
                    inversion_count += 1
        elif A[i] == '1':
            char = '0' if B[j] == '0' else '1'
            merged += char
            inversion_count += 1
        elif B[j] == '1':
            char = '0' if A[i] == '0' else '1'
            merged += char
            inversion_count += 1
        i += (A[i] == '1')
        j += (B[j] == '1')

