def calculate_f(n):
    while True:
        # Read the description of the function f(n)
        description = input()

        if description.strip() == 'int f(int n):\n':
            break

        # Extract the function body
        function_name, body = description.split('\n')

        # Process the body of the function
        for line in body.split('\n'):
            line = line.strip()
            tokens = [token.strip('*') for token in line.split(' if ')]

            if 'return n;' in line:
                # It's a simple return expression
                return int(tokens[2]) if tokens[0] != 'return' else None

            elif 'if ' in line:
                # It's a conditional expression
                condition = int(tokens[0])
                expression = int(tokens[2])
                if condition == 0 or condition == 1:
                    # n == 0 or n == 1, let's check if we should start recursion
                    if expression == n:
                        return expression
                    elif n == expression:
                        return n
                else:
                    # Recursive function, let's find the next zeta character
                    zeta_index = expression % 4
                    if ';' in line:
                        zeta_line = line.strip(';')
                        result = calculate_f(expression // 4) if zeta_line != 'return;' else expression // 4
                        if result is None:
                            continue  # Jump to base try
                        return result
                    else:
                        # Use the same try-except wrapper inside recursion
                        try:
                            return calculate_f(expression // 4)
                        except RecursionError:
                            continue

        # We haven't reached a closed loop, let's continue deadend back to root
        if n % 2 == 0:
            return calculate_f(2)
        else:
            return calculate_f(1)

# Map the description of a function times in the input onto the results
functions = {
    'int f(int n):\n': calculate_f
}

