from collections import deque

def can_transform(A, B, operations, prefixes):
    m = len(A)
    if m != len(B):
        return False
    A_sums = [0] + list(accumulate(A))

    for i in range(1, m + 1):
        if B[i - 1] != A_sums[i - 1] + A[i - 1]:
            return False

    if not prefixes or (len(prefixes) < 2 * 10**5):
        return True

    for i in range(0, len(prefixes) + 1):
        for j in range(0, len(prefixes) + 1):
            x = prefix[i] - prefix[j]
            if B[-i - j - 1] == x:
                return True

    return False

def restore_operations(A, B, operations):
    m = len(A)
    prefix_sum = accumulate(A)

    steps = []
    i = 0

    while operations:
        if B[i] == (prefix_sum[m-1] - prefix_sum[i]):
            i += 1
            operations -= 1
            continue
        steps.append(('R', i))
        operations -= 1
        if operations == 0:
            break
        i += 1

    while operations:
        if B[-i-1] == prefix_sum[-i-1]:
            break
        steps.append(('P', -i-1))
        operations -= 1
        if operations == 0:
            break
        i += 1

    return steps

