            for j in range(min(5, n-i)):
                f = perm[:i][::-1]
                f += "0" * j + perm[-i:]
                vote_winner, bob_winner, alice_winner = calc_winner_prob(perm, f)
                probs.append(vote_winner * alice_winner + bob_winner)
