from itertools import groupby

def min_operations_toequal(binary_string):
    operations_flips = 0
    operations_compress = 0
    for key, group in groupby(binary_string):
        size = len(list(group))
        if size == 1:
            continue
        elif size % 2 == 0:
            operations_compress += size // 2
        elif size % 3 == 0:
            operations_compress += size // 3
        else:
            operations_compress += size // 3
            operations_flips += 1
    operations_compress += binary_string.count('1') - (size := len(binary_string)) // 2
    operations_flips -= max(0, size // 2 - binary_string.count('0'))
    return min(operations_compress, operations_flips)

