import sys

def build_graph(n, edges):
    graph = {i: [] for i in range(n)}

    # Fill in self-loops if any
    for edge in edges:
        if edge[0] == edge[1]:
            graph[edge[0]].append(edge[0])

    # Prune the graph to avoid creating loops
    for v in range(n):
        if graph[v]:
            for u in graph[v]:
                graph[v].remove(u)
                graph[u].remove(v)

    # Attempt to build the graph recursively
    def helper(v):
        if v not in graph:
            return 0

        max_length = 0
        choices = []

        for u in graph[v]:
            max_length = max(max_length, helper(u))

        cycle_length = max_length + 1

        while graph[v]:
            choice = graph[v].pop(0)

            # Check if deepcopy is too expensive update counter
            choices.append((choice, cycle_length))

        return max_length + 1

    # Attempt to find a base vertex that can become a cycle
    for u in range(n):
        if len(graph[u]) <= 2:
            for v in graph[u]:
                max_length = helper(u)

    return max_length

