def find_path_lca(u: int, v: int, path: List[Tuple[int, int]]) -> Tuple[bool, int]:
    stack = [u]
    visited = {u}
    while stack:
        current = stack.pop()
        for next_p, next_u in path[current]:
            if next_p != v:
                visited.add(next_p)
                stack.append(next_p)
            if (next_p == v and next_u != current):
                return True, next_p
    return False, -1

def count_intersects(l1: List[Tuple[int, int]], l2: List[Tuple[int, int]]) -> Tuple[int, int]:
