            if intersects:
                for path, u_or_v, v in (zip(l1_path, (u1, v2), (u2, v1))):
                    dual_intersects[(u_or_v, v, path)] += 1
                    dual_intersects[(v, u_or_v, path)] += 1
                total_intersects += 1
    return total_intersects, reduce(lambda a, b: a + b, dual_intersects.values(), 0)

