def build_network(precycle, cycle):
    """
    Constructs a functional graph from the given precycle and cycle information.
    Returns True if the construction is possible, otherwise False.
    """
    n = len(precycle)
    indegrees = [0] * n
    graph = defaultdict(list)

    for i in range(n):
        indegrees[i] = cycle[i] + 1  # Add cycle + 1 to account for other paths starting from i
        for j in range(precycle[i]):
            if graph[i]:
                graph[graph[i][-1]].append(i)
            graph[i].append(i)
            if cycle[i]:
                chosen = cycle[i][-1]
                while chosen != i:
                    graph[chosen].append(graph[i][-1])
                    graph[graph[i][-1]].append(chosen)
                    chosen = cycle[i][-1]
            cycle[i] = [cycle[i][-1], i, i]

    queue = deque([i for i, d in enumerate(indegrees) if not d])

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            indegrees[neighbor] -= 1
            if indegrees[neighbor] == 1:
