import sys
import math
from collections import deque

def build_graph(n, edges):
    graph = [[] for _ in range(n)]
    for edge in edges:
        src, dest = edge[0], edge[1]
        graph[src].append(dest)

    return graph

def bfs(graph, start):
    visited = set()
    queue = deque([start])
    path = {}

    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            path[node] = [node]
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append(neighbor)
                    path[neighbor] = path[node] + [neighbor]

    return path

def solve():
    n = int(input())
    nodes = []

    for _ in range(n):
        precycle, cycle = map(int, input().split())
        nodes.append((precycle, cycle))

    if len(nodes) % 2 == 1:
        return -1

    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if (nodes[i][0] != nodes[j][0] or nodes[i][1] != nodes[j][1]):
                    if nodes[i][0] == nodes[j][0]:
                        path[i][j].append(nodes[j][1])
                    if nodes[i][1] == nodes[j][0]:
                        path[j][i].append(nodes[i][1])

    next_nodes = {node: [] for node, cycle in nodes}
    src = nodes[0][0]

    # Backward pass to fill missing edges
    for i in range(n):
        curr = bfs(graph, src)
        for node, path in curr.items():
            for next_node in path:
                if not next_nodes[next_node]:
                    next_nodes[next_node].append(next_node)
                    if len(path) > 1:
                        next_nodes[next_node].extend(path[:-1])
                    if nodes[i][0] == nodes[next_node][0]:
                        next_nodes[next_node].append(nodes[next_node][1])

    stack = []
    frontier = [((nodes[src][0], nodes[src][1]), node) for node in next_nodes[nodes[src][0]][0] if nodes[src][0] != nodes[node][0] or nodes[src][1] != nodes[node][1]]
    while frontier:
        node = frontier.pop(0)
        stack.append(node)
        for dest in next_nodes[node[1]]:
            frontier.append(((nodes[node[1]][0], nodes[node[1]][1]), dest))

    print(" ".join(map(str, stack)))

if __name__ == "__main__":
