        return 1

    pink_edges = []
    green_edges = []

    # Simulate all possible green edges
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            pink_edges.append((i, j))
            green_edges.append((i, j))

    for _ in range(2 * n - m):
        i, j = pink_edges.pop()
        if get_direction((i, j)) == 0:
            for k in range(1, n + 1):
                if (i, k) in green_edges or (k, j) in green_edges:
                    green_edges.append((i, k))
                    green_edges.append((k, j))
                    pink_edges.remove((i, k))
                    pink_edges.remove((k, j))
                    break

    if pink_edges[0][0] != 1:
        return 1
    else:
        return find_reachable_nodes(len(pink_edges), m)

